//! Swift language handler: queries and inheritance extraction.

/// Tree-sitter query for extracting Swift elements (classes, structs, functions, protocols).
pub const ELEMENT_QUERY: &str = r"
(class_declaration
  name: (type_identifier) @class_name) @class
(function_declaration
  name: (simple_identifier) @function_name) @function
(protocol_declaration
  name: (type_identifier) @protocol_name) @class
";

/// Tree-sitter query for extracting function calls.
pub const CALL_QUERY: &str = r"
(call_expression
  (simple_identifier) @call)
";

/// Tree-sitter query for extracting type references.
pub const REFERENCE_QUERY: &str = r"
(type_identifier) @type_ref
";

/// Tree-sitter query for extracting Swift imports.
pub const IMPORT_QUERY: &str = r"
(import_declaration) @import_path
";

/// Tree-sitter query for extracting definition and use sites.
pub const DEFUSE_QUERY: &str = r"
(property_declaration
  (pattern
    (simple_identifier) @write.property))
(simple_identifier) @read.usage
";

use tree_sitter::Node;

use crate::languages::get_node_text;

/// Extract inheritance information from a Swift class declaration node.
///
/// Walks `inheritance_specifier` children of the class declaration. The first
/// specifier is conventionally the superclass; subsequent specifiers are
/// protocol conformances. Results use `extends`/`conforms` prefixes.
#[must_use]
pub fn extract_inheritance(node: &Node, source: &str) -> Vec<String> {
    if node.kind() != "class_declaration" {
        return Vec::new();
    }

    let mut inherits = Vec::new();
    let mut seen_superclass = false;

    for i in 0..node.child_count() {
        if let Some(child) = node.child(i)
            && child.kind() == "inheritance_specifier"
            && let Some(type_node) = child.named_child(0)
            && let Some(text) = get_node_text(&type_node, source)
        {
            // The superclass may carry generic arguments; keep the base name only.
            let base = text.split('<').next().unwrap_or(&text).trim().to_string();
            if seen_superclass {
                inherits.push(format!("conforms {base}"));
            } else {
                inherits.push(format!("extends {base}"));
                seen_superclass = true;
            }
        }
    }

    inherits
}

#[cfg(test)]
mod tests {
    use super::*;
    use tree_sitter::{Parser, StreamingIterator};
----

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_language_for_extension_happy_path() {
        assert_eq!(language_for_extension("rs"), Some("rust"));
        assert_eq!(language_for_extension("py"), Some("python"));
        assert_eq!(language_for_extension("go"), Some("go"));
        assert_eq!(language_for_extension("java"), Some("java"));
        assert_eq!(language_for_extension("ts"), Some("typescript"));
        assert_eq!(language_for_extension("tsx"), Some("tsx"));
        assert_eq!(language_for_extension("swift"), Some("swift"));
        assert_eq!(language_for_extension("f90"), Some("fortran"));
        assert_eq!(language_for_extension("for"), Some("fortran"));
        assert_eq!(language_for_extension("ftn"), Some("fortran"));
        assert_eq!(language_for_extension("c"), Some("c"));
        assert_eq!(language_for_extension("cpp"), Some("cpp"));
        assert_eq!(language_for_extension("h"), Some("cpp"));
        assert_eq!(language_for_extension("hpp"), Some("cpp"));
        assert_eq!(language_for_extension("cc"), Some("cpp"));
        assert_eq!(language_for_extension("kt"), Some("kotlin"));
        assert_eq!(language_for_extension("kts"), Some("kotlin"));
    }

    /// The schema pattern must stay ECMAScript-valid (JSON Schema clients
    /// validate with ECMAScript regexes, so the pattern uses `[Xx]`
    /// per-character classes instead of `(?i)`): every supported extension
    /// must match and an unsupported one must not.
    #[test]
    #[cfg(feature = "schemars")]
    fn test_supported_file_ext_pattern_covers_all_extension_map_entries() {
        let pattern = crate::schema_helpers::supported_file_ext_pattern();
        assert!(!pattern.contains("(?i)"), "ECMAScript rejects (?i)");
        let re = regex::Regex::new(&format!("(?i){pattern}")).unwrap();
        for ext in supported_extensions() {
            assert!(
                re.is_match(&format!("src/file.{ext}")),
                "pattern does not match supported extension '{ext}'"
            );
